import numpy as np
from sklearn.ensemble import GradientBoostingRegressor

def stumps_vs_depth2_on_interaction(X_train, y_train, X_test, y_test):
    out = []
    for depth in (1, 2):
        model = GradientBoostingRegressor(learning_rate=0.1, n_estimators=200,
                                          max_depth=depth, random_state=0).fit(X_train, y_train)
        pred = model.predict(X_test)
        out.append(round(float(np.mean((y_test - pred) ** 2)), 4))
    return tuple(out)
